#include <string>
#include <iostream>

using namespace std;

static string data = "";

int main(){
    clock_t c_start = clock();
    int chunksize = 13;
    string::iterator itr;
    long prod;
    long maxprod = 0;
    string winner;
    string datachunk;
    for (itr = data.begin(); itr != data.end()-chunksize+1; itr++) {
        prod = 1;
        datachunk = "";
        for (int t = 0; t != chunksize; t++) {
            prod *= long(*(itr+t) - 48); // converting ASCII into numbers: '0' is 48, '1' is 49 etc.
            datachunk += *(itr+t);
        }
        if (prod > maxprod) {
            maxprod = prod;
            winner = datachunk;
        }
    }
    clock_t c_end = clock();
    cout << endl;
    cout << winner << " " << maxprod << endl;
    cout << 1000.0*(c_end - c_start) / CLOCKS_PER_SEC << " ms\n";
    return 0;
}